import mongoose from 'mongoose';

const academyClassSchema = new mongoose.Schema({
  title: { type: String, required: true },
  category: { type: String, required: true },
  duration: { type: String, required: true },
  level: { type: String, required: true },
  price: { type: String, required: true }, // Stored as String to match "Rs. 35,000"
  description: { type: String, required: true },
  syllabus: [{ type: String }], // Array of strings
  popular: { type: Boolean, default: false }
}, { 
  timestamps: true 
});
export default mongoose.model('AcademyClass', academyClassSchema);